import sys

def lexicographicallySmallest(S, k):
    n = len(S)

    # Check if n is a power of 2
    def is_power_of_two(x):
        return x > 0 and (x & (x - 1)) == 0

    if is_power_of_two(n):
        k = k // 2
    else:
        k = k * 2

    # Check if removal is possible
    if k < 0 or k >= n:
        return "-1"

    # We need to keep (n - k) characters
    keep_count = n - k
    if keep_count == 0:
        return "-1"

    # Use a stack to build the result
    stack = []
    removed_count = 0

    for char in S:
        while stack and removed_count < k and stack[-1] > char:
            stack.pop()
            removed_count += 1
        stack.append(char)

    # If we haven't removed enough characters yet, remove from the end
    while removed_count < k:
        stack.pop()
        removed_count += 1

    result = ''.join(stack)

    if not result:
        return "-1"

    return result

